package driver

import (
	"context"
	"errors"
	"sync"

	"github.com/Zen1th53/marshal/internal/marshal"
)

type runtimeObservationKey struct{}
type runtimeObservationSink struct {
	mu        sync.Mutex
	records   []marshal.CommandRecord
	submitted bool
	closed    bool
	err       error
}

// ReportRuntimeObserved records structured observations generated by the
// in-process governed runtime. Worker stdout is never submitted here. Each
// launched callback receives its own sink, and publication is single-use.
// Calls outside that callback have no observation authority.
func ReportRuntimeObserved(ctx context.Context, records []marshal.CommandRecord) error {
	sink, ok := ctx.Value(runtimeObservationKey{}).(*runtimeObservationSink)
	if !ok {
		return nil
	}
	sink.mu.Lock()
	defer sink.mu.Unlock()
	refuse := func(err error) error { sink.err = errors.Join(sink.err, err); return err }
	if err := ctx.Err(); err != nil {
		return refuse(err)
	}
	if sink.closed {
		return refuse(errors.New("runtime observation callback completed"))
	}
	total := 0
	if len(records) > privateRuntimeObservationCapacity(records) {
		return refuse(errors.New("runtime observations exceed record bound"))
	}
	for _, record := range records {
		total += len(record.Command) + len(record.Output)
		if total > maxOutput {
			return refuse(errors.New("runtime observations exceed byte bound"))
		}
	}
	if sink.submitted {
		return refuse(errors.New("runtime observations already submitted"))
	}
	sink.records = append([]marshal.CommandRecord(nil), records...)
	sink.submitted = true
	return nil
}

func (s *runtimeObservationSink) read() ([]marshal.CommandRecord, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.closed = true
	return append([]marshal.CommandRecord(nil), s.records...), s.err
}
